+// forEachPrefix iterates over all leaf nodes whose keys start with the specified keyPrefix.
+func (tr *tree) forEachPrefix(key Key, callback Callback, opts int) traverseAction {
+	// Handle edge cases
+	if tr.root == nil {
+		return traverseContinue
+	}
+
+	// Navigate to the node that represents the prefix
+	prefixNode := tr.navigateToPrefix(key)
+	if prefixNode == nil {
+		return traverseContinue
+	}
+
+	// Set up traversal options - only traverse leaf nodes
+	options := traverseOptions(opts)
+	options &= traverseOpts(TraverseLeaf | TraverseReverse) // Keep only leaf and reverse options
+
+	// Create a callback that filters for keys with the specified prefix
+	prefixCallback := func(node Node) bool {
+		if node.Kind() == Leaf {
+			// Check if the leaf's key starts with our prefix
+			current, ok := node.(*nodeRef)
+			if !ok {
+				return false
+			}
+
+			if leaf := current.leaf(); leaf.prefixMatch(key) {
+				return callback(current)
+			}
+		}
+		return true // Continue traversal for non-matching nodes
+	}
+
+	// Traverse only the subtree under prefixNode
+	tr.forEachRecursively(prefixNode, prefixCallback, options.hasReverse())
+
+	return traverseContinue
+}
+
+// navigateToPrefix navigates the tree to find the node where keys with the given prefix would be located.
+func (tr *tree) navigateToPrefix(prefix Key) *nodeRef {
+	keyOffset := 0
+	current := tr.root
+
+	for current != nil && keyOffset <= len(prefix) {
+		if current.isLeaf() {
+			// If we reach a leaf, check if its key could match our prefix
+			leaf := current.leaf()
+			// If the leaf's key is long enough and starts with our prefix, this is a match
+			if len(leaf.key) >= len(prefix) && bytes.Equal(leaf.key[:len(prefix)], prefix) {
+				return current
+			}
+			// If the leaf's key is shorter but is a prefix of our search prefix, 
+			// we still want to traverse from here
+			if len(leaf.key) < len(prefix) && bytes.Equal(prefix[:len(leaf.key)], leaf.key) {
+				return current
+			}
+			return nil
+		}
+
+		// For internal nodes, check the prefix
+		node := current.node()
+		if node.prefixLen > 0 {
+			// Check how much of our prefix matches the node's prefix
+			prefixLen := current.match(prefix, keyOffset)
+			matchedLen := minInt(prefixLen, minInt(int(node.prefixLen), maxPrefixLen))
+			
+			// If our prefix is shorter than the node's prefix and matches so far,
+			// this is where we want to start traversal
+			if keyOffset+matchedLen == len(prefix) {
+				return current
+			}
+			
+			// If there's a mismatch in the node's prefix, no match
+			if prefixLen != minInt(int(node.prefixLen), maxPrefixLen) {
+				// But if we've consumed our entire prefix, this is where we start
+				if keyOffset+prefixLen == len(prefix) {
+					return current
+				}
+				return nil
+			}
+
+			keyOffset += int(node.prefixLen)
+		}
+
+		// If we've consumed our entire prefix, this is the node we want
+		if keyOffset >= len(prefix) {
+			return current
+		}
+
+		// Continue to children
+		next := current.findChildByKey(prefix, keyOffset)
+		if *next == nil {
+			// No child for this character, but we might still have a match
+			return current
+		}
+		
+		current = *next
+		keyOffset++
+	}
+
+	return current
+}
