+		return true // Continue traversal for non-matching nodes
+	}
+
+	// Traverse only the subtree under prefixNode
+	tr.forEachRecursively(prefixNode, prefixCallback, options.hasReverse())
+
+	return traverseContinue
+}
+
+// navigateToPrefix navigates the tree to find the node where keys with the given prefix would be located.
+func (tr *tree) navigateToPrefix(prefix Key) *nodeRef {
+	keyOffset := 0
+	current := tr.root
+
+	for current != nil && keyOffset < len(prefix) {
+		if current.isLeaf() {
+			// If we reach a leaf, check if its key could match our prefix
+			leaf := current.leaf()
+			if len(leaf.key) >= len(prefix) && bytes.Equal(leaf.key[:len(prefix)], prefix) {
+				return current
+			}
+			// If the leaf's key is shorter or doesn't match the prefix at this point, no match
+			return nil
+		}
+
+		// For internal nodes, check the prefix
+		node := current.node()
+		if node.prefixLen > 0 {
+			// Compare node's prefix with our prefix
+			maxPrefixCheck := minInt(int(node.prefixLen), maxPrefixLen)
+			remainingPrefixLen := len(prefix) - keyOffset
+			
+			// If our prefix is shorter than the node's prefix, check if it matches the beginning
+			if remainingPrefixLen < maxPrefixCheck {
+				for i := 0; i < remainingPrefixLen; i++ {
+					if node.prefix[i] != prefix[keyOffset+i] {
+						return nil // No match
+					}
+				}
+				// Prefix matches, this is the node we want
+				return current
+			}
+			
+			// Our prefix is longer or equal, check if node's prefix matches
+			for i := 0; i < maxPrefixCheck; i++ {
+				if node.prefix[i] != prefix[keyOffset+i] {
+					return nil // No match
+				}
+			}
+			
+			// Node's prefix matches, continue to children
+			keyOffset += maxPrefixCheck
+			
+			// If we've consumed our entire prefix, this is the node we want
+			if keyOffset >= len(prefix) {
+				return current
+			}
+		}
+
+		// Continue to children
+		next := current.findChildByKey(prefix, keyOffset)
+		if *next == nil {
+			// No child for this character, but we might still have a match
+			// if we've consumed our entire prefix
+			if keyOffset >= len(prefix) {
+				return current
+			}
+			return nil
+		}
+		
+		current = *next
+		keyOffset++
+	}
+
+	return current
+}
