+package art
+
+// findPrefixNode finds the node that represents the given prefix.
+// It navigates the tree to find the node where traversal of keys with the given prefix should begin.
+func (tr *tree) findPrefixNode(prefix Key) *nodeRef {
+	if tr.root == nil || len(prefix) == 0 {
+		return tr.root
+	}
+
+	keyOffset := 0
+	current := tr.root
+
+	for current != nil && keyOffset < len(prefix) {
+		if current.isLeaf() {
+			// If we reach a leaf, check if its key starts with the prefix
+			leaf := current.leaf()
+			if leaf.prefixMatch(prefix) {
+				return current
+			}
+			return nil
+		}
+
+		curNode := current.node()
+		if curNode.prefixLen > 0 {
+			// Check how much of our prefix matches the node's prefix
+			matchedLen := 0
+			maxCheckLen := minInt(int(curNode.prefixLen), maxPrefixLen)
+			remainingPrefixLen := len(prefix) - keyOffset
+			
+			// Compare the node's prefix with our prefix
+			for matchedLen < maxCheckLen && matchedLen < remainingPrefixLen {
+				if curNode.prefix[matchedLen] != prefix[keyOffset+matchedLen] {
+					break
+				}
+				matchedLen++
+			}
+			
+			// If our prefix doesn't fully match the node's prefix
+			if matchedLen < maxCheckLen && matchedLen < remainingPrefixLen {
+				return nil // No match
+			}
+			
+			// If the node's prefix is longer than our remaining prefix, and we've matched so far
+			// then this is the right node to start traversal
+			if matchedLen == remainingPrefixLen && matchedLen < maxCheckLen {
+				return current
+			}
+			
+			// If our prefix is longer than the node's prefix, continue to children
+			keyOffset += matchedLen
+			
+			// If we've consumed our entire prefix, this is the node we want
+			if keyOffset >= len(prefix) {
+				return current
+			}
+		}
+
+		// Continue navigating down the tree
+		next := current.findChildByKey(prefix, keyOffset)
+		if *next != nil {
+			current = *next
+			keyOffset++
+		} else {
+			// No direct child for this prefix character
+			// If we've consumed our entire prefix, this is where we start traversal
+			if keyOffset >= len(prefix) {
+				return current
+			}
+			return nil
+		}
+	}
+
+	return current
+}
+
+// prefixMatchCallback wraps the user callback to filter nodes by prefix
+func (tr *tree) prefixMatchCallback(prefix Key, callback Callback) Callback {
+	return func(node Node) bool {
+		if node.Kind() == Leaf {
+			current, ok := node.(*nodeRef)
+			if !ok {
+				return false
+			}
+			
+			if leaf := current.leaf(); leaf.prefixMatch(prefix) {
+				return callback(current)
+			}
+			return true
+		}
+		// For non-leaf nodes, continue traversal
+		return true
+	}
+}
+
+func (tr *tree) forEachPrefix(key Key, callback Callback, opts int) traverseAction {
+	options := traverseOptions(opts)
+	
+	// Find the node where prefix traversal should start
+	startNode := tr.findPrefixNode(key)
+	if startNode == nil {
+		return traverseContinue
+	}
+	
+	// If the start node is a leaf, check if it matches the prefix and call callback directly
+	if startNode.isLeaf() {
+		if leaf := startNode.leaf(); leaf.prefixMatch(key) {
+			callback(startNode)
+		}
+		return traverseContinue
+	}
+	
+	// Traverse the subtree starting from the prefix node
+	filteredCallback := tr.prefixMatchCallback(key, callback)
+	tr.forEachRecursively(startNode, filteredCallback, options.hasReverse())
+	
+	return traverseContinue
+}
